<div id="tutor-longitud-naranja" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b; user-select: none;">
<div class="lng-header">Cambio de unidades de longitud</div>
<div class="lng-box"><!-- Enunciado -->
<div class="lng-enunciado-card"><span id="lng-val-origen">77,8</span> <span id="lng-uni-origen" class="lng-unidad-destacada">dam</span> <span>=</span> <span style="display: inline-block; min-width: 70px; border-bottom: 2px dashed #fdba74; text-align: center; color: #ea580c;" id="lng-hueco-preview">?</span> <span id="lng-uni-destino" class="lng-unidad-destacada">cm</span></div>
<div class="lng-instruccion">Escribe la solución sin ceros innecesarios y pulsa Intro (o haz clic en Comprobar).</div>
<!-- Entrada de solución -->
<div class="lng-input-row"><span class="lng-label-sol">Solución</span> <input type="text" id="lng-input-sol" class="lng-input" autocomplete="off" placeholder="Ej: 854" />
<div role="button" id="lng-btn-comprobar" class="lng-btn" tabindex="0">Comprobar</div>
</div>
<!-- Banner de acierto -->
<div id="lng-ok-banner" class="lng-ok-banner"><span>¡Correcto! Has realizado bien la conversión.</span>
<div role="button" id="lng-btn-siguiente-ok" class="lng-btn" tabindex="0">Otro ejercicio</div>
</div>
<!-- Panel de ayuda visual con escalera -->
<div id="lng-ayuda-panel" class="lng-ayuda-panel">
<div class="lng-ayuda-grid">
<div class="lng-ayuda-texto">
<div class="lng-sol-titulo">Solución:</div>
<div id="lng-sol-operacion" class="lng-sol-operacion"></div>
<div class="lng-sol-sub">Introduce la solución correcta arriba para continuar, o pasa al siguiente ejercicio.</div>
<div id="lng-explicacion-pasos" class="lng-explicacion-pasos"></div>
</div>
<div class="lng-ayuda-svg" id="lng-escalera-container"><!-- SVG generado por JS --></div>
</div>
</div>
</div>
<script>
    (function() {
        const unidades = [
            { sim: 'km', nombre: 'kilómetros' },
            { sim: 'hm', nombre: 'hectómetros' },
            { sim: 'dam', nombre: 'decámetros' },
            { sim: 'm', nombre: 'metros' },
            { sim: 'dm', nombre: 'decímetros' },
            { sim: 'cm', nombre: 'centímetros' },
            { sim: 'mm', nombre: 'milímetros' }
        ];

        let ejercicioActual = {};

        const elValOrigen = document.getElementById('lng-val-origen');
        const elUniOrigen = document.getElementById('lng-uni-origen');
        const elUniDestino = document.getElementById('lng-uni-destino');
        const elHuecoPreview = document.getElementById('lng-hueco-preview');
        const inpSol = document.getElementById('lng-input-sol');
        const btnComprobar = document.getElementById('lng-btn-comprobar');
        const okBanner = document.getElementById('lng-ok-banner');
        const btnSiguienteOk = document.getElementById('lng-btn-siguiente-ok');
        const ayudaPanel = document.getElementById('lng-ayuda-panel');
        const elSolOperacion = document.getElementById('lng-sol-operacion');
        const elExplicacion = document.getElementById('lng-explicacion-pasos');
        const elEscalera = document.getElementById('lng-escalera-container');

        function formatearES(num) {
            let limpio = parseFloat(num.toPrecision(12));
            return limpio.toString().replace('.', ',');
        }

        function generarEjercicio() {
            inpSol.value = '';
            inpSol.style.borderColor = '#f97316';
            inpSol.style.backgroundColor = '#ffffff';
            elHuecoPreview.innerText = '?';
            okBanner.style.setProperty('display', 'none', 'important');
            ayudaPanel.style.setProperty('display', 'none', 'important');

            let idxOrigen = Math.floor(Math.random() * unidades.length);
            let salto;
            do {
                salto = Math.floor(Math.random() * 7) - 3;
            } while (salto === 0 || (idxOrigen + salto < 0) || (idxOrigen + salto >= unidades.length));

            let idxDestino = idxOrigen + salto;

            let tieneDecimal = Math.random() < 0.65;
            let base = Math.floor(Math.random() * 89) + 2;
            let valorOrigen = tieneDecimal ? parseFloat((base + (Math.floor(Math.random() * 9) + 1) / 10).toFixed(1)) : base;

            let factor = Math.pow(10, Math.abs(salto));
            let solucionNum = salto > 0 ? valorOrigen * factor : valorOrigen / factor;
            solucionNum = parseFloat(solucionNum.toPrecision(12));

            ejercicioActual = {
                idxOrigen: idxOrigen,
                idxDestino: idxDestino,
                salto: salto,
                valorOrigen: valorOrigen,
                factor: factor,
                solucionNum: solucionNum,
                solucionStr: formatearES(solucionNum)
            };

            elValOrigen.innerText = formatearES(valorOrigen);
            elUniOrigen.innerText = unidades[idxOrigen].sim;
            elUniDestino.innerText = unidades[idxDestino].sim;

            setTimeout(() => inpSol.focus(), 50);
        }

        function dibujarEscaleraSVG(idxOrig, idxDest, salto, factor) {
            const wStep = 56;
            const hStep = 30;
            // Márgenes amplios para alojar la flecha exterior sin recortes
            const startX = 28;
            const startY = 26;
            const svgW = startX + unidades.length * wStep + 34;
            const svgH = startY + unidades.length * hStep + 34;

            let svg = `<svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}" xmlns="http://www.w3.org/2000/svg">`;

            unidades.forEach((u, i) => {
                let x = startX + i * wStep;
                let y = startY + i * hStep;
                let esActivo = (i === idxOrig || i === idxDest);
                let strokeColor = esActivo ? '#ea580c' : '#fdba74';
                let strokeW = esActivo ? '3' : '1.5';
                let fillColor = esActivo ? '#ffedd5' : '#ffffff';
                let textColor = esActivo ? '#c2410c' : '#334155';
                let fontWeight = esActivo ? '800' : '600';

                svg += `<rect x="${x}" y="${y}" width="${wStep}" height="${hStep}" fill="${fillColor}" stroke="${strokeColor}" stroke-width="${strokeW}" rx="2" />`;
                svg += `<text x="${x + 12}" y="${y + 21}" font-family="Segoe UI, Arial, sans-serif" font-size="16" font-weight="${fontWeight}" fill="${textColor}">${u.sim}</text>`;
            });

            // Coordenadas de la flecha completamente POR FUERA de los peldaños
            let x1, y1, x2, y2;
            if (salto > 0) {
                // Bajada (multiplicar) -> Paralela por ARRIBA-DERECHA de la escalera
                x1 = startX + idxOrig * wStep + wStep + 14;
                y1 = startY + idxOrig * hStep - 4;
                x2 = startX + idxDest * wStep + wStep + 14;
                y2 = startY + idxDest * hStep - 4;
            } else {
                // Subida (dividir) -> Paralela por ABAJO-IZQUIERDA de la escalera
                x1 = startX + idxOrig * wStep - 14;
                y1 = startY + idxOrig * hStep + hStep + 4;
                x2 = startX + idxDest * wStep - 14;
                y2 = startY + idxDest * hStep + hStep + 4;
            }

            svg += `
                <defs>
                    <marker id="flecha-naranja-ext" markerWidth="10" markerHeight="10" refX="7" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#ea580c" stroke="#431407" stroke-width="0.6"/>
                    </marker>
                </defs>
                <line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#ea580c" stroke-width="4" stroke-linecap="round" marker-end="url(#flecha-naranja-ext)" />
            `;

            svg += `</svg>`;
            return svg;
        }

        function mostrarAyuda() {
            const uOrig = unidades[ejercicioActual.idxOrigen].nombre;
            const uDest = unidades[ejercicioActual.idxDestino].nombre;
            const opSimbolo = ejercicioActual.salto > 0 ? '·' : ':';
            const opVerbo = ejercicioActual.salto > 0 ? 'Bajamos' : 'Subimos';
            const numSaltos = Math.abs(ejercicioActual.salto);
            const textoEscalones = numSaltos === 1 ? '1 escalón' : `${numSaltos} escalones`;

            elSolOperacion.innerText = `${formatearES(ejercicioActual.valorOrigen)} ${opSimbolo} ${ejercicioActual.factor} = ${ejercicioActual.solucionStr}`;

            elExplicacion.innerHTML = `
                Desde <strong>${uOrig}</strong> hasta <strong>${uDest}</strong>:<br>
                ${opVerbo} <strong>${textoEscalones}</strong> &rarr; <strong style="color:#ea580c; font-size:1.2rem;">${opSimbolo} ${ejercicioActual.factor}</strong>
            `;

            elEscalera.innerHTML = dibujarEscaleraSVG(
                ejercicioActual.idxOrigen,
                ejercicioActual.idxDestino,
                ejercicioActual.salto,
                ejercicioActual.factor
            );

            ayudaPanel.style.setProperty('display', 'block', 'important');
        }

        function comprobarRespuesta() {
            let raw = inpSol.value.trim().replace(',', '.');
            if (raw === '' || isNaN(Number(raw))) {
                inpSol.focus();
                return;
            }

            let tieneCerosInnecesarios = false;
            if (raw.includes('.')) {
                if (raw.endsWith('0') || raw.endsWith('.')) {
                    tieneCerosInnecesarios = true;
                }
            }

            let valUsuario = parseFloat(raw);
            let esCorrectoNum = Math.abs(valUsuario - ejercicioActual.solucionNum) < 1e-9;

            if (esCorrectoNum && !tieneCerosInnecesarios) {
                inpSol.style.borderColor = '#16a34a';
                inpSol.style.backgroundColor = '#f0fdf4';
                elHuecoPreview.innerText = ejercicioActual.solucionStr;
                ayudaPanel.style.setProperty('display', 'none', 'important');
                okBanner.style.setProperty('display', 'flex', 'important');
            } else {
                inpSol.style.borderColor = '#dc2626';
                inpSol.style.backgroundColor = '#fef2f2';
                mostrarAyuda();
                inpSol.focus();
                inpSol.select();
            }
        }

        btnComprobar.addEventListener('click', comprobarRespuesta);
        btnSiguienteOk.addEventListener('click', generarEjercicio);
        inpSol.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                comprobarRespuesta();
            }
        });

        setTimeout(generarEjercicio, 100);
    })();
    </script>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

