<div id="tutor-masa-naranja" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b; user-select: none;">
<div class="ms-header">Cambio de unidades de masa</div>
<div class="ms-box"><!-- Enunciado -->
<div class="ms-enunciado-card"><span id="ms-val-origen">507</span> <span id="ms-uni-origen" class="ms-unidad-destacada">g</span> <span>=</span> <span style="display: inline-block; min-width: 75px; border-bottom: 2px dashed #fdba74; text-align: center; color: #ea580c;" id="ms-hueco-preview">?</span> <span id="ms-uni-destino" class="ms-unidad-destacada">q</span></div>
<div class="ms-instruccion">Escribe la solución sin ceros innecesarios y pulsa Intro (o haz clic en Comprobar).</div>
<!-- Entrada de solución -->
<div class="ms-input-row"><span class="ms-label-sol">Solución</span> <input type="text" id="ms-input-sol" class="ms-input" autocomplete="off" placeholder="Ej: 0,05" />
<div role="button" id="ms-btn-comprobar" class="ms-btn" tabindex="0">Comprobar</div>
</div>
<!-- Banner de acierto -->
<div id="ms-ok-banner" class="ms-ok-banner"><span>¡Correcto! Has realizado bien la conversión.</span>
<div role="button" id="ms-btn-siguiente-ok" class="ms-btn" tabindex="0">Otro ejercicio</div>
</div>
<!-- Panel de ayuda visual con escalera -->
<div id="ms-ayuda-panel" class="ms-ayuda-panel">
<div class="ms-ayuda-grid">
<div class="ms-ayuda-texto">
<div class="ms-sol-titulo">Solución:</div>
<div id="ms-sol-operacion" class="ms-sol-operacion"></div>
<div class="ms-sol-sub">Introduce la solución correcta arriba para continuar, o pasa al siguiente ejercicio.</div>
<div id="ms-explicacion-pasos" class="ms-explicacion-pasos"></div>
</div>
<div class="ms-ayuda-svg" id="ms-escalera-container"><!-- SVG generado por JS --></div>
</div>
</div>
</div>
<script>
    (function() {
        const unidades = [
            { sim: 't',   nombre: 'toneladas' },
            { sim: 'q',   nombre: 'quintales métricos' },
            { sim: 'mag', nombre: 'miriagramos' },
            { sim: 'kg',  nombre: 'kilogramos' },
            { sim: 'hg',  nombre: 'hectogramos' },
            { sim: 'dag', nombre: 'decagramos' },
            { sim: 'g',   nombre: 'gramos' },
            { sim: 'dg',  nombre: 'decigramos' },
            { sim: 'cg',  nombre: 'centigramos' },
            { sim: 'mg',  nombre: 'miligramos' }
        ];

        let ejercicioActual = {};

        const elValOrigen = document.getElementById('ms-val-origen');
        const elUniOrigen = document.getElementById('ms-uni-origen');
        const elUniDestino = document.getElementById('ms-uni-destino');
        const elHuecoPreview = document.getElementById('ms-hueco-preview');
        const inpSol = document.getElementById('ms-input-sol');
        const btnComprobar = document.getElementById('ms-btn-comprobar');
        const okBanner = document.getElementById('ms-ok-banner');
        const btnSiguienteOk = document.getElementById('ms-btn-siguiente-ok');
        const ayudaPanel = document.getElementById('ms-ayuda-panel');
        const elSolOperacion = document.getElementById('ms-sol-operacion');
        const elExplicacion = document.getElementById('ms-explicacion-pasos');
        const elEscalera = document.getElementById('ms-escalera-container');

        function formatearES(num) {
            let limpio = parseFloat(num.toPrecision(12));
            // Evitar notación científica en números pequeños (ej: 0.00005)
            let str = limpio.toFixed(10).replace(/\.?0+$/, '');
            return str.replace('.', ',');
        }

        function generarEjercicio() {
            inpSol.value = '';
            inpSol.style.borderColor = '#f97316';
            inpSol.style.backgroundColor = '#ffffff';
            elHuecoPreview.innerText = '?';
            okBanner.style.setProperty('display', 'none', 'important');
            ayudaPanel.style.setProperty('display', 'none', 'important');

            // Elegir índice origen (0..9) y salto de 1 a 4 escalones para nivel básico
            let idxOrigen = Math.floor(Math.random() * unidades.length);
            let salto;
            do {
                salto = Math.floor(Math.random() * 9) - 4; // entre -4 y +4
            } while (salto === 0 || (idxOrigen + salto < 0) || (idxOrigen + salto >= unidades.length));

            let idxDestino = idxOrigen + salto;

            let tieneDecimal = Math.random() < 0.6;
            let base = Math.floor(Math.random() * 95) + 2; // 2 a 96
            let valorOrigen = tieneDecimal ? parseFloat((base + (Math.floor(Math.random() * 9) + 1) / 10).toFixed(1)) : base;

            let factor = Math.pow(10, Math.abs(salto));
            let solucionNum = salto > 0 ? valorOrigen * factor : valorOrigen / factor;
            solucionNum = parseFloat(solucionNum.toPrecision(12));

            ejercicioActual = {
                idxOrigen: idxOrigen,
                idxDestino: idxDestino,
                salto: salto,
                valorOrigen: valorOrigen,
                factor: factor,
                solucionNum: solucionNum,
                solucionStr: formatearES(solucionNum)
            };

            elValOrigen.innerText = formatearES(valorOrigen);
            elUniOrigen.innerText = unidades[idxOrigen].sim;
            elUniDestino.innerText = unidades[idxDestino].sim;

            setTimeout(() => inpSol.focus(), 50);
        }

        function dibujarEscaleraSVG(idxOrig, idxDest, salto) {
            const wStep = 48;
            const hStep = 26;
            const startX = 24;
            const startY = 22;
            const svgW = startX + unidades.length * wStep + 28;
            const svgH = startY + unidades.length * hStep + 28;

            let svg = `<svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}" xmlns="http://www.w3.org/2000/svg">`;

            unidades.forEach((u, i) => {
                let x = startX + i * wStep;
                let y = startY + i * hStep;
                let esActivo = (i === idxOrig || i === idxDest);
                let strokeColor = esActivo ? '#ea580c' : '#fdba74';
                let strokeW = esActivo ? '2.8' : '1.5';
                let fillColor = esActivo ? '#ffedd5' : '#ffffff';
                let textColor = esActivo ? '#c2410c' : '#334155';
                let fontWeight = esActivo ? '800' : '600';

                svg += `<rect x="${x}" y="${y}" width="${wStep}" height="${hStep}" fill="${fillColor}" stroke="${strokeColor}" stroke-width="${strokeW}" rx="2" />`;
                svg += `<text x="${x + wStep / 2}" y="${y + 18}" text-anchor="middle" font-family="Segoe UI, Arial, sans-serif" font-size="14" font-weight="${fontWeight}" fill="${textColor}">${u.sim}</text>`;
            });

            // Flecha exterior paralela a la escalera
            let x1, y1, x2, y2;
            if (salto > 0) {
                // Bajada (multiplicar) -> Por arriba-derecha
                x1 = startX + idxOrig * wStep + wStep + 12;
                y1 = startY + idxOrig * hStep - 3;
                x2 = startX + idxDest * wStep + wStep + 12;
                y2 = startY + idxDest * hStep - 3;
            } else {
                // Subida (dividir) -> Por abajo-izquierda
                x1 = startX + idxOrig * wStep - 12;
                y1 = startY + idxOrig * hStep + hStep + 3;
                x2 = startX + idxDest * wStep - 12;
                y2 = startY + idxDest * hStep + hStep + 3;
            }

            svg += `
                <defs>
                    <marker id="flecha-masa-ext" markerWidth="9" markerHeight="9" refX="6.5" refY="3.2" orient="auto">
                        <polygon points="0 0, 9 3.2, 0 6.4" fill="#ea580c" stroke="#431407" stroke-width="0.6"/>
                    </marker>
                </defs>
                <line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#ea580c" stroke-width="3.5" stroke-linecap="round" marker-end="url(#flecha-masa-ext)" />
            `;

            svg += `</svg>`;
            return svg;
        }

        function mostrarAyuda() {
            const uOrig = unidades[ejercicioActual.idxOrigen].nombre;
            const uDest = unidades[ejercicioActual.idxDestino].nombre;
            const opSimbolo = ejercicioActual.salto > 0 ? '·' : ':';
            const opVerbo = ejercicioActual.salto > 0 ? 'Bajamos' : 'Subimos';
            const numSaltos = Math.abs(ejercicioActual.salto);
            const textoEscalones = numSaltos === 1 ? '1 escalón' : `${numSaltos} escalones`;

            elSolOperacion.innerText = `${formatearES(ejercicioActual.valorOrigen)} ${opSimbolo} ${ejercicioActual.factor} = ${ejercicioActual.solucionStr}`;

            elExplicacion.innerHTML = `
                Desde <strong>${uOrig}</strong> hasta <strong>${uDest}</strong>:<br>
                ${opVerbo} <strong>${textoEscalones}</strong> &rarr; <strong style="color:#ea580c; font-size:1.2rem;">${opSimbolo} ${ejercicioActual.factor}</strong>
            `;

            elEscalera.innerHTML = dibujarEscaleraSVG(
                ejercicioActual.idxOrigen,
                ejercicioActual.idxDestino,
                ejercicioActual.salto
            );

            ayudaPanel.style.setProperty('display', 'block', 'important');
        }

        function comprobarRespuesta() {
            let raw = inpSol.value.trim().replace(',', '.');
            if (raw === '' || isNaN(Number(raw))) {
                inpSol.focus();
                return;
            }

            let tieneCerosInnecesarios = false;
            if (raw.includes('.')) {
                if (raw.endsWith('0') || raw.endsWith('.')) {
                    tieneCerosInnecesarios = true;
                }
            }

            let valUsuario = parseFloat(raw);
            let esCorrectoNum = Math.abs(valUsuario - ejercicioActual.solucionNum) < 1e-11;

            if (esCorrectoNum && !tieneCerosInnecesarios) {
                inpSol.style.borderColor = '#16a34a';
                inpSol.style.backgroundColor = '#f0fdf4';
                elHuecoPreview.innerText = ejercicioActual.solucionStr;
                ayudaPanel.style.setProperty('display', 'none', 'important');
                okBanner.style.setProperty('display', 'flex', 'important');
            } else {
                inpSol.style.borderColor = '#dc2626';
                inpSol.style.backgroundColor = '#fef2f2';
                mostrarAyuda();
                inpSol.focus();
                inpSol.select();
            }
        }

        btnComprobar.addEventListener('click', comprobarRespuesta);
        btnSiguienteOk.addEventListener('click', generarEjercicio);
        inpSol.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                comprobarRespuesta();
            }
        });

        setTimeout(generarEjercicio, 100);
    })();
    </script>
