<script>
    (function() {
        // Escala ordenada de mayor a menor y factor respecto a la unidad inmediatamente inferior
        const unidades = [
            { sim: 'siglos', nombre: 'siglos',               factorSiguiente: 10 },  // 1 siglo = 10 décadas
            { sim: 'décadas',nombre: 'décadas',              factorSiguiente: 10 },  // 1 década = 10 años
            { sim: 'años',   nombre: 'años',                 factorSiguiente: 365 }, // 1 año = 365 días
            { sim: 'd',      nombre: 'días',                 factorSiguiente: 24 },  // 1 día = 24 horas
            { sim: 'h',      nombre: 'horas',                factorSiguiente: 60 },  // 1 hora = 60 minutos
            { sim: 'min',    nombre: 'minutos',              factorSiguiente: 60 },  // 1 minuto = 60 segundos
            { sim: 's',      nombre: 'segundos',             factorSiguiente: 10 },  // 1 s = 10 ds
            { sim: 'ds',     nombre: 'décimas de segundo',   factorSiguiente: 10 },  // 1 ds = 10 cs
            { sim: 'cs',     nombre: 'centésimas de segundo',factorSiguiente: 10 },  // 1 cs = 10 ms
            { sim: 'ms',     nombre: 'milisegundos',         factorSiguiente: 1 }
        ];

        let ejercicioActual = {};

        const elValOrigen = document.getElementById('tmp-val-origen');
        const elUniOrigen = document.getElementById('tmp-uni-origen');
        const elUniDestino = document.getElementById('tmp-uni-destino');
        const elHuecoPreview = document.getElementById('tmp-hueco-preview');
        const inpSol = document.getElementById('tmp-input-sol');
        const btnComprobar = document.getElementById('tmp-btn-comprobar');
        const okBanner = document.getElementById('tmp-ok-banner');
        const btnSiguienteOk = document.getElementById('tmp-btn-siguiente-ok');
        const ayudaPanel = document.getElementById('tmp-ayuda-panel');
        const elSolOperacion = document.getElementById('tmp-sol-operacion');
        const elRutaContainer = document.getElementById('tmp-ruta-container');
        const elExplicacion = document.getElementById('tmp-explicacion-pasos');

        function formatearES(num) {
            let limpio = parseFloat(num.toPrecision(12));
            let str = limpio.toFixed(10).replace(/\.?0+$/, '');
            return str.replace('.', ',');
        }

        function esDecimalExacto(num) {
            // Verifica que el resultado no sea un decimal periódico largo (máximo 4 decimales significativos)
            let redondeado = Math.round(num * 100000) / 100000;
            return Math.abs(num - redondeado) < 1e-11;
        }

        function generarEjercicio() {
            inpSol.value = '';
            inpSol.style.borderColor = '#f97316';
            inpSol.style.backgroundColor = '#ffffff';
            elHuecoPreview.innerText = '?';
            okBanner.style.setProperty('display', 'none', 'important');
            ayudaPanel.style.setProperty('display', 'none', 'important');

            let idxOrigen, idxDestino, salto, factorTotal, valorOrigen, solucionNum;
            let valido = false;

            while (!valido) {
                idxOrigen = Math.floor(Math.random() * unidades.length);
                // Saltos de 1 a 3 pasos para nivel básico
                salto = Math.floor(Math.random() * 7) - 3;
                if (salto === 0 || (idxOrigen + salto < 0) || (idxOrigen + salto >= unidades.length)) continue;

                idxDestino = idxOrigen + salto;

                // Calcular factor total multiplicando los factores intermedios
                factorTotal = 1;
                let minIdx = Math.min(idxOrigen, idxDestino);
                let maxIdx = Math.max(idxOrigen, idxDestino);
                for (let i = minIdx; i < maxIdx; i++) {
                    factorTotal *= unidades[i].factorSiguiente;
                }

                // Evitar factores gigantescos (ej: siglos a días = 36500 está bien, pero limitar a <= 100000)
                if (factorTotal > 100000) continue;

                if (salto > 0) {
                    // Multiplicar (pasar a unidad más pequeña)
                    let tieneDec = Math.random() < 0.45;
                    let base = Math.floor(Math.random() * 25) + 1;
                    valorOrigen = tieneDec ? parseFloat((base + [0.5, 0.2, 0.25, 0.1][Math.floor(Math.random()*4)]).toFixed(2)) : base;
                    solucionNum = valorOrigen * factorTotal;
                    valido = true;
                } else {
                    // Dividir (pasar a unidad más grande): elegimos un múltiplo amigable del factorTotal
                    let multiplicadores = [0.5, 1, 1.5, 2, 2.5, 3, 4, 5, 10, 12, 20];
                    let mult = multiplicadores[Math.floor(Math.random() * multiplicadores.length)];
                    valorOrigen = factorTotal * mult;
                    solucionNum = valorOrigen / factorTotal;
                    if (esDecimalExacto(valorOrigen) && esDecimalExacto(solucionNum) && valorOrigen <= 500000) {
                        valido = true;
                    }
                }
            }

            solucionNum = parseFloat(solucionNum.toPrecision(12));

            ejercicioActual = {
                idxOrigen: idxOrigen,
                idxDestino: idxDestino,
                salto: salto,
                valorOrigen: valorOrigen,
                factorTotal: factorTotal,
                solucionNum: solucionNum,
                solucionStr: formatearES(solucionNum)
            };

            elValOrigen.innerText = formatearES(valorOrigen);
            elUniOrigen.innerText = unidades[idxOrigen].sim;
            elUniDestino.innerText = unidades[idxDestino].sim;

            setTimeout(() => inpSol.focus(), 50);
        }

        function mostrarAyuda() {
            const idxOrig = ejercicioActual.idxOrigen;
            const idxDest = ejercicioActual.idxDestino;
            const baja = ejercicioActual.salto > 0; // true = unidad mayor a menor (multiplicar)
            const opSimbolo = baja ? '·' : ':';
            const opVerbo = baja ? 'multiplicamos' : 'dividimos';

            elSolOperacion.innerText = `${formatearES(ejercicioActual.valorOrigen)} ${opSimbolo} ${ejercicioActual.factorTotal} = ${ejercicioActual.solucionStr}`;

            // Construir la ruta visual paso a paso solo con los nodos implicados
            let htmlRuta = '';
            let desgloseFactores = [];

            if (baja) {
                for (let i = idxOrig; i <= idxDest; i++) {
                    let esExtremo = (i === idxOrig || i === idxDest);
                    htmlRuta += `<div class="tmp-nodo ${esExtremo ? 'extremo' : ''}">${unidades[i].sim}</div>`;
                    if (i < idxDest) {
                        let f = unidades[i].factorSiguiente;
                        desgloseFactores.push(f);
                        htmlRuta += `
                            <div class="tmp-salto-flecha">
                                <span class="tmp-salto-badge">· ${f}</span>
                                <span class="tmp-salto-linea">&rarr;</span>
                            </div>
                        `;
                    }
                }
            } else {
                for (let i = idxOrig; i >= idxDest; i--) {
                    let esExtremo = (i === idxOrig || i === idxDest);
                    htmlRuta += `<div class="tmp-nodo ${esExtremo ? 'extremo' : ''}">${unidades[i].sim}</div>`;
                    if (i > idxDest) {
                        let f = unidades[i - 1].factorSiguiente;
                        desgloseFactores.push(f);
                        htmlRuta += `
                            <div class="tmp-salto-flecha">
                                <span class="tmp-salto-badge">: ${f}</span>
                                <span class="tmp-salto-linea">&rarr;</span>
                            </div>
                        `;
                    }
                }
            }

            elRutaContainer.innerHTML = htmlRuta;

            let textoFactorTotal = desgloseFactores.length > 1
                ? `(${desgloseFactores.join(' · ')} = <strong>${ejercicioActual.factorTotal}</strong>)`
                : `<strong>${ejercicioActual.factorTotal}</strong>`;

            elExplicacion.innerHTML = `
                Para pasar de <strong>${unidades[idxOrig].nombre}</strong> a <strong>${unidades[idxDest].nombre}</strong> 
                ${opVerbo} por ${textoFactorTotal} &rarr; <strong style="color:#ea580c; font-size:1.15rem;">${opSimbolo} ${ejercicioActual.factorTotal}</strong>
            `;

            ayudaPanel.style.setProperty('display', 'block', 'important');
        }

        function comprobarRespuesta() {
            let raw = inpSol.value.trim().replace(',', '.');
            if (raw === '' || isNaN(Number(raw))) {
                inpSol.focus();
                return;
            }

            let tieneCerosInnecesarios = false;
            if (raw.includes('.')) {
                if (raw.endsWith('0') || raw.endsWith('.')) {
                    tieneCerosInnecesarios = true;
                }
            }

            let valUsuario = parseFloat(raw);
            let esCorrectoNum = Math.abs(valUsuario - ejercicioActual.solucionNum) < 1e-11;

            if (esCorrectoNum && !tieneCerosInnecesarios) {
                inpSol.style.borderColor = '#16a34a';
                inpSol.style.backgroundColor = '#f0fdf4';
                elHuecoPreview.innerText = ejercicioActual.solucionStr;
                ayudaPanel.style.setProperty('display', 'none', 'important');
                okBanner.style.setProperty('display', 'flex', 'important');
            } else {
                inpSol.style.borderColor = '#dc2626';
                inpSol.style.backgroundColor = '#fef2f2';
                mostrarAyuda();
                inpSol.focus();
                inpSol.select();
            }
        }

        btnComprobar.addEventListener('click', comprobarRespuesta);
        btnSiguienteOk.addEventListener('click', generarEjercicio);
        inpSol.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                comprobarRespuesta();
            }
        });

        setTimeout(generarEjercicio, 100);
    })();
    </script>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

