    </style>
<div id="tutor-volumen-naranja" style="width: 100%; box-sizing: border-box; font-family: 'Segoe UI', Arial, sans-serif; color: #1e293b; user-select: none;">
<div class="vol-header">Cambio de unidades de volumen</div>
<div class="vol-box"><!-- Pregunta principal -->
<div class="vol-pregunta-card" id="vol-pregunta-texto">¿Cuántos <span class="vol-destacado">dm<sup>3</sup></span> son <span class="vol-destacado">4,5 m<sup>3</sup></span>?</div>
<div class="vol-cuerpo-grid"><!-- Columna izquierda: Escalera vertical de mano -->
<div class="vol-col-escalera" id="vol-escalera-svg"><!-- SVG generado por JS --></div>
<!-- Columna derecha: Entrada y explicación -->
<div class="vol-col-trabajo">
<div class="vol-instruccion">Introduce el resultado sin ceros innecesarios y pulsa <strong>Intro</strong> o <strong>Comprobar</strong>:</div>
<div class="vol-input-row"><input type="text" id="vol-input-sol" class="vol-input" autocomplete="off" placeholder="Ej: 4500" />
<div role="button" id="vol-btn-comprobar" class="vol-btn" tabindex="0">Comprobar</div>
<div role="button" id="vol-btn-ver-sol" class="vol-btn-sec" tabindex="0">Ver solución</div>
</div>
<!-- Banner de acierto -->
<div id="vol-ok-banner" class="vol-ok-banner"><span>¡Correcto! Has realizado bien la conversión.</span>
<div role="button" id="vol-btn-otro-ok" class="vol-btn" tabindex="0">Otro ejercicio</div>
</div>
<!-- Desarrollo paso a paso -->
<div id="vol-explicacion-box" class="vol-explicacion-box">
<div id="vol-explicacion-contenido"></div>
<div style="margin-top: 14px;">
<div role="button" id="vol-btn-otro-exp" class="vol-btn" tabindex="0">Otro ejercicio</div>
</div>
</div>
</div>
</div>
</div>
<script>
    (function() {
        const unidades = [
            { sim: 'km',  nombre: 'kilómetros cúbicos' },
            { sim: 'hm',  nombre: 'hectómetros cúbicos' },
            { sim: 'dam', nombre: 'decámetros cúbicos' },
            { sim: 'm',   nombre: 'metros cúbicos' },
            { sim: 'dm',  nombre: 'decímetros cúbicos' },
            { sim: 'cm',  nombre: 'centímetros cúbicos' },
            { sim: 'mm',  nombre: 'milímetros cúbicos' }
        ];

        let ejercicioActual = {};

        const elPregunta = document.getElementById('vol-pregunta-texto');
        const elEscalera = document.getElementById('vol-escalera-svg');
        const inpSol = document.getElementById('vol-input-sol');
        const btnComprobar = document.getElementById('vol-btn-comprobar');
        const btnVerSol = document.getElementById('vol-btn-ver-sol');
        const okBanner = document.getElementById('vol-ok-banner');
        const btnOtroOk = document.getElementById('vol-btn-otro-ok');
        const expBox = document.getElementById('vol-explicacion-box');
        const expContenido = document.getElementById('vol-explicacion-contenido');
        const btnOtroExp = document.getElementById('vol-btn-otro-exp');

        function formatearES(num) {
            let limpio = parseFloat(num.toPrecision(12));
            let str = limpio.toFixed(12).replace(/\.?0+$/, '');
            return str.replace('.', ',');
        }

        function dibujarEscaleraVertical(idxOrig, idxDest) {
            const svgW = 148;
            const svgH = 266;
            const railLeft = 44;
            const railRight = 128;
            const topY = 12;
            const bottomY = 254;
            const stepH = 33;

            let svg = `<svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}" xmlns="http://www.w3.org/2000/svg">`;

            // Largueros verticales de la escalera en tono naranja oscuro
            svg += `<line x1="${railLeft}" y1="${topY}" x2="${railLeft}" y2="${bottomY}" stroke="#c2410c" stroke-width="4.5" stroke-linecap="round"/>`;
            svg += `<line x1="${railRight}" y1="${topY}" x2="${railRight}" y2="${bottomY}" stroke="#c2410c" stroke-width="4.5" stroke-linecap="round"/>`;

            // Peldaños y etiquetas
            unidades.forEach((u, i) => {
                let yRung = topY + 34 + i * stepH;
                let yText = yRung - 8;
                let esActivo = (i === idxOrig || i === idxDest);

                if (esActivo) {
                    svg += `<rect x="${railLeft + 3}" y="${yRung - stepH + 3}" width="${railRight - railLeft - 6}" height="${stepH - 5}" fill="#ffedd5" rx="3" />`;
                }

                svg += `<line x1="${railLeft}" y1="${yRung}" x2="${railRight}" y2="${yRung}" stroke="#f97316" stroke-width="3"/>`;

                let colorTxt = esActivo ? '#c2410c' : '#94a3b8';
                let weightTxt = esActivo ? '800' : '600';
                svg += `
                    <text x="${(railLeft + railRight) / 2}" y="${yText}" text-anchor="middle" font-family="Segoe UI, Arial, sans-serif" font-size="17" font-weight="${weightTxt}" fill="${colorTxt}">
                        ${u.sim}<tspan dy="-6" font-size="11">3</tspan>
                    </text>
                `;
            });

            // Flecha exterior a la izquierda del larguero izquierdo
            let arrowX = 20;
            let yOrigCenter = topY + 18 + idxOrig * stepH;
            let yDestCenter = topY + 18 + idxDest * stepH;

            svg += `
                <defs>
                    <marker id="flecha-vol-vert" markerWidth="10" markerHeight="10" refX="7" refY="3.5" orient="auto">
                        <polygon points="0 0, 10 3.5, 0 7" fill="#ea580c" stroke="#431407" stroke-width="0.6"/>
                    </marker>
                </defs>
                <line x1="${arrowX}" y1="${yOrigCenter}" x2="${arrowX}" y2="${yDestCenter}" stroke="#ea580c" stroke-width="4.5" stroke-linecap="round" marker-end="url(#flecha-vol-vert)" />
            `;

            svg += `</svg>`;
            return svg;
        }

        function generarEjercicio() {
            inpSol.value = '';
            inpSol.style.borderColor = '#f97316';
            inpSol.style.backgroundColor = '#ffffff';
            okBanner.style.setProperty('display', 'none', 'important');
            expBox.style.setProperty('display', 'none', 'important');

            // Saltos de 1 a 2 escalones (factores de 1000 o 1000000) adecuados a nivel básico
            let idxOrigen = Math.floor(Math.random() * unidades.length);
            let salto;
            do {
                salto = Math.floor(Math.random() * 5) - 2; // entre -2 y +2
            } while (salto === 0 || (idxOrigen + salto < 0) || (idxOrigen + salto >= unidades.length));

            let idxDestino = idxOrigen + salto;
            let numEscalones = Math.abs(salto);
            let factor = Math.pow(1000, numEscalones);

            // Número origen amigable (entero de 1 o 2 cifras, o con 1 decimal)
            let tieneDec = Math.random() < 0.45;
            let base = Math.floor(Math.random() * 35) + 2; // 2 a 36
            let valorOrigen = tieneDec ? parseFloat((base + (Math.floor(Math.random() * 9) + 1) / 10).toFixed(1)) : base;

            let solucionNum = salto > 0 ? valorOrigen * factor : valorOrigen / factor;
            solucionNum = parseFloat(solucionNum.toPrecision(12));

            ejercicioActual = {
                idxOrigen: idxOrigen,
                idxDestino: idxDestino,
                salto: salto,
                numEscalones: numEscalones,
                valorOrigen: valorOrigen,
                factor: factor,
                solucionNum: solucionNum,
                solucionStr: formatearES(solucionNum)
            };

            const simOrig = `${unidades[idxOrigen].sim}<sup>3</sup>`;
            const simDest = `${unidades[idxDestino].sim}<sup>3</sup>`;

            elPregunta.innerHTML = `¿Cuántos <span class="vol-destacado">${simDest}</span> son <span class="vol-destacado">${formatearES(valorOrigen)} ${simOrig}</span>?`;
            elEscalera.innerHTML = dibujarEscaleraVertical(idxOrigen, idxDestino);

            setTimeout(() => inpSol.focus(), 50);
        }

        function mostrarExplicacion() {
            const simOrig = `${unidades[ejercicioActual.idxOrigen].sim}<sup>3</sup>`;
            const simDest = `${unidades[ejercicioActual.idxDestino].sim}<sup>3</sup>`;
            const n = ejercicioActual.numEscalones;
            const baja = ejercicioActual.salto > 0;

            const verboDir = baja ? 'bajar' : 'subir';
            const verboOp = baja ? 'multiplicar por' : 'dividir entre';
            const verboOpCap = baja ? 'Multiplicar por' : 'Dividir entre';
            const txtEscalones = n === 1 ? '1 escalón' : `${n} escalones`;
            const txtVeces = n === 1 ? '1 vez' : `${n} veces`;

            let operacionHTML = '';
            if (baja) {
                operacionHTML = `<span style="color:#0369a1; font-weight:800;">${formatearES(ejercicioActual.valorOrigen)} ${simOrig} = ${formatearES(ejercicioActual.valorOrigen)} · ${ejercicioActual.factor} ${simDest}</span>`;
            } else {
                operacionHTML = `
                    <span style="color:#0369a1; font-weight:800;">${formatearES(ejercicioActual.valorOrigen)} ${simOrig} = </span>
                    <span class="vol-fraccion-visual">
                        <span class="vol-fraccion-num">${formatearES(ejercicioActual.valorOrigen)}</span>
                        <span class="vol-fraccion-den">${ejercicioActual.factor}</span>
                    </span>
                    <span style="color:#0369a1; font-weight:800;"> ${simDest}</span>
                `;
            }

            let equivalenciaHTML = n > 1 
                ? `<p style="margin: 8px 0;">${verboOpCap} 1000 ${txtVeces} equivale a ${verboOp} <strong>${ejercicioActual.factor}</strong>. La solución es:</p>`
                : `<p style="margin: 8px 0;">Al ser 1 escalón, ${verboOp} <strong>1000</strong>. La solución es:</p>`;

            expContenido.innerHTML = `
                <div>
                    Para pasar de <strong>${simOrig}</strong> a <strong>${simDest}</strong> hay que <strong>${verboDir} ${txtEscalones}</strong>. 
                    Hay que ${verboOp} <strong>1000</strong> ${txtVeces}.
                </div>
                ${equivalenciaHTML}
                <div style="margin: 12px 0;">${operacionHTML}</div>
                <div class="vol-resultado-final">
                    ${formatearES(ejercicioActual.valorOrigen)} ${simOrig} = ${ejercicioActual.solucionStr} ${simDest}
                </div>
            `;

            expBox.style.setProperty('display', 'block', 'important');
        }

        function comprobarRespuesta() {
            let raw = inpSol.value.trim().replace(',', '.');
            if (raw === '' || isNaN(Number(raw))) {
                inpSol.focus();
                return;
            }

            let tieneCerosInnecesarios = false;
            if (raw.includes('.')) {
                if (raw.endsWith('0') || raw.endsWith('.')) {
                    tieneCerosInnecesarios = true;
                }
            }

            let valUsuario = parseFloat(raw);
            let esCorrectoNum = Math.abs(valUsuario - ejercicioActual.solucionNum) < 1e-12;

            if (esCorrectoNum && !tieneCerosInnecesarios) {
                inpSol.style.borderColor = '#16a34a';
                inpSol.style.backgroundColor = '#f0fdf4';
                expBox.style.setProperty('display', 'none', 'important');
                okBanner.style.setProperty('display', 'flex', 'important');
            } else {
                inpSol.style.borderColor = '#dc2626';
                inpSol.style.backgroundColor = '#fef2f2';
                okBanner.style.setProperty('display', 'none', 'important');
                mostrarExplicacion();
                inpSol.focus();
                inpSol.select();
            }
        }

        btnComprobar.addEventListener('click', comprobarRespuesta);
        btnVerSol.addEventListener('click', () => {
            okBanner.style.setProperty('display', 'none', 'important');
            mostrarExplicacion();
        });
        btnOtroOk.addEventListener('click', generarEjercicio);
        btnOtroExp.addEventListener('click', generarEjercicio);

        inpSol.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                comprobarRespuesta();
            }
        });

        setTimeout(generarEjercicio, 100);
    })();
    </script>
</div>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

