<script>
    (function() {
        // Niveles emparejados 1 a 1: 0 (m3 <-> kl), 1 (dm3 <-> l), 2 (cm3 <-> ml)
        const niveles = [
            { volHTML: 'm<sup>3</sup>',  volNombre: 'metros cúbicos',      capHTML: 'kl', capNombre: 'kilolitros' },
            { volHTML: 'dm<sup>3</sup>', volNombre: 'decímetros cúbicos',  capHTML: 'l',  capNombre: 'litros' },
            { volHTML: 'cm<sup>3</sup>', volNombre: 'centímetros cúbicos', capHTML: 'ml', capNombre: 'mililitros' }
        ];

        let ejercicioActual = {};

        const elPregunta = document.getElementById('cv-pregunta-texto');
        const inpSol = document.getElementById('cv-input-sol');
        const btnComprobar = document.getElementById('cv-btn-comprobar');
        const btnVerSol = document.getElementById('cv-btn-ver-sol');
        const okBanner = document.getElementById('cv-ok-banner');
        const btnOtroOk = document.getElementById('cv-btn-otro-ok');
        const expBox = document.getElementById('cv-explicacion-box');
        const expContenido = document.getElementById('cv-explicacion-contenido');
        const btnOtroExp = document.getElementById('cv-btn-otro-exp');

        function formatearES(num) {
            let limpio = parseFloat(num.toPrecision(12));
            let str = limpio.toFixed(10).replace(/\.?0+$/, '');
            return str.replace('.', ',');
        }

        function actualizarCeldasActivas(tipoOrig, nivelOrig, tipoDest, nivelDest) {
            for (let i = 0; i < 3; i++) {
                document.getElementById(`cv-cell-vol-${i}`).classList.remove('activa');
                document.getElementById(`cv-cell-cap-${i}`).classList.remove('activa');
            }
            document.getElementById(`cv-cell-${tipoOrig}-${nivelOrig}`).classList.add('activa');
            document.getElementById(`cv-cell-${tipoDest}-${nivelDest}`).classList.add('activa');
        }

        function generarEjercicio() {
            inpSol.value = '';
            inpSol.style.borderColor = '#f97316';
            inpSol.style.backgroundColor = '#ffffff';
            okBanner.style.setProperty('display', 'none', 'important');
            expBox.style.setProperty('display', 'none', 'important');

            // Elegir sentido: 'vol2cap' o 'cap2vol'
            let deVolACap = Math.random() < 0.5;
            let tipoOrig = deVolACap ? 'vol' : 'cap';
            let tipoDest = deVolACap ? 'cap' : 'vol';

            // Elegir nivel origen (0, 1 o 2) y nivel destino (0, 1 o 2)
            // Prohibir salto entre extremos (0 <-> 2)
            let nivelOrig = Math.floor(Math.random() * 3);
            let nivelDest;
            do {
                nivelDest = Math.floor(Math.random() * 3);
            } while (Math.abs(nivelOrig - nivelDest) === 2);

            let salto = nivelDest - nivelOrig; // -1 (sube), 0 (mismo nivel), +1 (baja)

            // Generar valor origen amigable
            let tieneDec = Math.random() < 0.45;
            let base = Math.floor(Math.random() * 45) + 2; // 2 a 46
            let valorOrigen = tieneDec ? parseFloat((base + (Math.floor(Math.random() * 9) + 1) / 10).toFixed(1)) : base;

            let solucionNum;
            if (salto === 0) {
                solucionNum = valorOrigen;
            } else if (salto === 1) {
                solucionNum = valorOrigen * 1000;
            } else {
                solucionNum = valorOrigen / 1000;
            }
            solucionNum = parseFloat(solucionNum.toPrecision(12));

            let simOrig = deVolACap ? niveles[nivelOrig].volHTML : niveles[nivelOrig].capHTML;
            let simDest = deVolACap ? niveles[nivelDest].capHTML : niveles[nivelDest].volHTML;

            ejercicioActual = {
                deVolACap: deVolACap,
                tipoOrig: tipoOrig,
                tipoDest: tipoDest,
                nivelOrig: nivelOrig,
                nivelDest: nivelDest,
                salto: salto,
                simOrig: simOrig,
                simDest: simDest,
                valorOrigen: valorOrigen,
                solucionNum: solucionNum,
                solucionStr: formatearES(solucionNum)
            };

            elPregunta.innerHTML = `¿Cuántos <span class="cv-destacado">${simDest}</span> son <span class="cv-destacado">${formatearES(valorOrigen)} ${simOrig}</span>?`;
            actualizarCeldasActivas(tipoOrig, nivelOrig, tipoDest, nivelDest);

            setTimeout(() => inpSol.focus(), 50);
        }

        function mostrarExplicacion() {
            const ej = ejercicioActual;
            const nOrig = niveles[ej.nivelOrig];
            const nDest = niveles[ej.nivelDest];

            // Unidad puente en la magnitud de destino al mismo nivel que el origen
            const puenteDestHTML = ej.deVolACap ? nOrig.capHTML : nOrig.volHTML;

            let paso1HTML = `<div><strong>1. Equivalencia directa:</strong> Sabemos que <strong style="color:#c2410c;">1 ${ej.simOrig} = 1 ${puenteDestHTML}</strong>, así que ${formatearES(ej.valorOrigen)} ${ej.simOrig} = <strong>${formatearES(ej.valorOrigen)} ${puenteDestHTML}</strong>.</div>`;

            let paso2HTML = '';
            let operacionHTML = '';

            if (ej.salto === 0) {
                paso2HTML = `<p style="margin: 8px 0;"><strong>2. Resultado directo:</strong> Como ambas unidades están en el mismo nivel, el valor numérico no cambia.</p>`;
                operacionHTML = `<span style="color:#0369a1; font-weight:800;">${formatearES(ej.valorOrigen)} ${ej.simOrig} = ${ej.solucionStr} ${ej.simDest}</span>`;
            } else if (ej.salto === 1) {
                paso2HTML = `<p style="margin: 8px 0;"><strong>2. Bajamos 1 nivel:</strong> Para pasar de <strong>${puenteDestHTML}</strong> a <strong>${ej.simDest}</strong> multiplicamos por <strong>1000</strong>.</p>`;
                operacionHTML = `<span style="color:#0369a1; font-weight:800;">${formatearES(ej.valorOrigen)} · 1000 = ${ej.solucionStr} ${ej.simDest}</span>`;
            } else {
                paso2HTML = `<p style="margin: 8px 0;"><strong>2. Subimos 1 nivel:</strong> Para pasar de <strong>${puenteDestHTML}</strong> a <strong>${ej.simDest}</strong> dividimos entre <strong>1000</strong>.</p>`;
                operacionHTML = `
                    <span class="cv-fraccion-visual">
                        <span class="cv-fraccion-num">${formatearES(ej.valorOrigen)}</span>
                        <span class="cv-fraccion-den">1000</span>
                    </span>
                    <span style="color:#0369a1; font-weight:800;"> = ${ej.solucionStr} ${ej.simDest}</span>
                `;
            }

            expContenido.innerHTML = `
                ${paso1HTML}
                ${paso2HTML}
                <div style="margin: 10px 0;">${operacionHTML}</div>
                <div class="cv-resultado-final">
                    ${formatearES(ej.valorOrigen)} ${ej.simOrig} = ${ej.solucionStr} ${ej.simDest}
                </div>
            `;

            expBox.style.setProperty('display', 'block', 'important');
        }

        function comprobarRespuesta() {
            let raw = inpSol.value.trim().replace(',', '.');
            if (raw === '' || isNaN(Number(raw))) {
                inpSol.focus();
                return;
            }

            let tieneCerosInnecesarios = false;
            if (raw.includes('.')) {
                if (raw.endsWith('0') || raw.endsWith('.')) {
                    tieneCerosInnecesarios = true;
                }
            }

            let valUsuario = parseFloat(raw);
            let esCorrectoNum = Math.abs(valUsuario - ejercicioActual.solucionNum) < 1e-11;

            if (esCorrectoNum && !tieneCerosInnecesarios) {
                inpSol.style.borderColor = '#16a34a';
                inpSol.style.backgroundColor = '#f0fdf4';
                expBox.style.setProperty('display', 'none', 'important');
                okBanner.style.setProperty('display', 'flex', 'important');
            } else {
                inpSol.style.borderColor = '#dc2626';
                inpSol.style.backgroundColor = '#fef2f2';
                okBanner.style.setProperty('display', 'none', 'important');
                mostrarExplicacion();
                inpSol.focus();
                inpSol.select();
            }
        }

        btnComprobar.addEventListener('click', comprobarRespuesta);
        btnVerSol.addEventListener('click', () => {
            okBanner.style.setProperty('display', 'none', 'important');
            mostrarExplicacion();
        });
        btnOtroOk.addEventListener('click', generarEjercicio);
        btnOtroExp.addEventListener('click', generarEjercicio);

        inpSol.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                comprobarRespuesta();
            }
        });

        setTimeout(generarEjercicio, 100);
    })();
    </script>
