<script>
(function() {
  const angulosData = [
    { id: 0, label: "π/2", num: "π", den: "2", val: Math.PI / 2, div: 2, steps: 1, dir: 1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 2 partes." },
    { id: 1, label: "-π/2", num: "-π", den: "2", val: -Math.PI / 2, div: 2, steps: 1, dir: -1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 2 partes (sentido negativo u horario)." },
    { id: 2, label: "π", num: "π", den: "", val: Math.PI, div: 1, steps: 1, dir: 1,
      desc: "El ángulo π corresponde exactamente a media circunferencia (180°)." },
    { id: 3, label: "3π/2", num: "3π", den: "2", val: 3 * Math.PI / 2, div: 2, steps: 3, dir: 1,
      desc: "Los puntos amarillos indican que cada semicircunferencia (π) se ha dividido en 2 partes, tomando 3 de ellas." },
    { id: 4, label: "π/3", num: "π", den: "3", val: Math.PI / 3, div: 3, steps: 1, dir: 1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 3 partes." },
    { id: 5, label: "π/4", num: "π", den: "4", val: Math.PI / 4, div: 4, steps: 1, dir: 1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 4 partes." },
    { id: 6, label: "3π/4", num: "3π", den: "4", val: 3 * Math.PI / 4, div: 4, steps: 3, dir: 1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 4 partes, tomando 3 de ellas." },
    { id: 7, label: "5π/6", num: "5π", den: "6", val: 5 * Math.PI / 6, div: 6, steps: 5, dir: 1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 6 partes." },
    { id: 8, label: "2π", num: "2π", den: "", val: 2 * Math.PI, div: 1, steps: 2, dir: 1,
      desc: "El ángulo 2π equivale a dos semicircunferencias completas (una vuelta entera de 360°)." },
    { id: 9, label: "5π/4", num: "5π", den: "4", val: 5 * Math.PI / 4, div: 4, steps: 5, dir: 1,
      desc: "Los puntos amarillos indican que cada semicircunferencia (π) se ha dividido en 4 partes, tomando 5 de ellas." },
    { id: 10, label: "11π/6", num: "11π", den: "6", val: 11 * Math.PI / 6, div: 6, steps: 11, dir: 1,
      desc: "Los puntos amarillos indican que cada semicircunferencia (π) se ha dividido en 6 partes, tomando 11 de ellas." },
    { id: 11, label: "-2π", num: "-2π", den: "", val: -2 * Math.PI, div: 1, steps: 2, dir: -1,
      desc: "El ángulo -2π equivale a una vuelta completa (360°) recorrida en sentido negativo (horario)." },
    { id: 12, label: "-3π/4", num: "-3π", den: "4", val: -3 * Math.PI / 4, div: 4, steps: 3, dir: -1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 4 partes, tomando 3 en sentido negativo." },
    { id: 13, label: "-π/4", num: "-π", den: "4", val: -Math.PI / 4, div: 4, steps: 1, dir: -1,
      desc: "Los puntos amarillos indican que la semicircunferencia (π) se ha dividido en 4 partes, tomando 1 en sentido negativo." },
    { id: 14, label: "3π", num: "3π", den: "", val: 3 * Math.PI, div: 1, steps: 3, dir: 1,
      desc: "El ángulo 3π corresponde a 3 semicircunferencias (una vuelta completa de 2π más media vuelta adicional)." },
    { id: 15, label: "6", num: "6", den: "", val: 6, div: 0, steps: 0, dir: 1,
      desc: "El recorrido de longitud igual a 6 radios.<br>Cada punto rojo marca un radián." }
  ];

  let activeId = null;

  function renderTituloHTML(item) {
    if (item.den) {
      return `
        <span style="display: inline-flex; flex-direction: column; align-items: center; line-height: 1.05; vertical-align: middle;">
          <span style="padding: 0 6px; border-bottom: 2.5px solid #1d4ed8;">${item.num}</span>
          <span style="padding: 2px 6px 0 6px;">${item.den}</span>
        </span>
        <span>radianes</span>
      `;
    } else {
      return `<span>${item.num} radianes</span>`;
    }
  }

  // Calcula posición exterior evitando pisar los ejes X e Y
  function obtenerPosEtiquetaExterior(cx, cy, R, ang) {
    const labelR = R + 28;
    const cosA = Math.cos(ang);
    const sinA = Math.sin(ang);
    let lx = cx + labelR * cosA;
    let ly = cy - labelR * sinA;

    // Si cae sobre el eje Y (cosA ≈ 0): desplazamos ligeramente a la derecha del eje
    if (Math.abs(cosA) < 0.08) {
      lx = cx + 22;
      ly = cy - (R + 24) * Math.sign(sinA);
    }
    // Si cae sobre el eje X (sinA ≈ 0): desplazamos ligeramente por encima del eje
    else if (Math.abs(sinA) < 0.08) {
      lx = cx + (R + 24) * Math.sign(cosA);
      ly = cy - 22;
    }

    return { x: lx, y: ly };
  }

  function dibujarEscena(item) {
    const svg = document.getElementById('rad-svg');
    if (!svg) return;

    const cx = 260;
    const cy = 200;
    const R = 132;
    let html = '';

    // 1. Sombreado del sector circular del ángulo (si hay ángulo activo)
    if (item) {
      const totalAbs = Math.abs(item.val);
      if (totalAbs >= 2 * Math.PI - 0.001) {
        // Círculo completo sombreado (más intenso si da más de una vuelta)
        const opacidad = totalAbs > 2.5 * Math.PI ? "0.24" : "0.15";
        html += `<circle cx="${cx}" cy="${cy}" r="${R}" fill="rgba(2, 132, 199, ${opacidad})" />`;
      } else {
        // Sector circular exacto desde 0 hasta item.val
        const x1 = cx + R;
        const y1 = cy;
        const x2 = cx + R * Math.cos(item.val);
        const y2 = cy - R * Math.sin(item.val);
        const largeArc = totalAbs > Math.PI ? 1 : 0;
        const sweepFlag = item.val > 0 ? 0 : 1; // En SVG Y crece hacia abajo: sentido antihorario es sweep=0
        const sectorPath = `M ${cx} ${cy} L ${x1.toFixed(2)} ${y1.toFixed(2)} A ${R} ${R} 0 ${largeArc} ${sweepFlag} ${x2.toFixed(2)} ${y2.toFixed(2)} Z`;
        html += `<path d="${sectorPath}" fill="rgba(2, 132, 199, 0.16)" />`;
      }
    }

    // 2. Ejes coordenados con marcas de graduación
    html += `<line x1="25" y1="${cy}" x2="495" y2="${cy}" stroke="#64748b" stroke-width="1.3" />`;
    html += `<line x1="${cx}" y1="18" x2="${cx}" y2="382" stroke="#64748b" stroke-width="1.3" />`;

    // Marcas en eje X
    for (let x = cx - 220; x <= cx + 220; x += 13.2) {
      let isMajor = Math.abs((x - cx) % 52.8) < 1;
      let tick = isMajor ? 4 : 2;
      html += `<line x1="${x.toFixed(1)}" y1="${cy - tick}" x2="${x.toFixed(1)}" y2="${cy + tick}" stroke="#64748b" stroke-width="1" />`;
    }
    // Marcas en eje Y
    for (let y = cy - 171.6; y <= cy + 171.6; y += 13.2) {
      let isMajor = Math.abs((y - cy) % 52.8) < 1;
      let tick = isMajor ? 4 : 2;
      html += `<line x1="${cx - tick}" y1="${y.toFixed(1)}" x2="${cx + tick}" y2="${y.toFixed(1)}" stroke="#64748b" stroke-width="1" />`;
    }

    // 3. Circunferencia base
    html += `<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="#94a3b8" stroke-width="1.6" />`;

    if (!item) {
      svg.innerHTML = html;
      return;
    }

    // 4. Semirrecta origen (eje X positivo en azul)
    html += `<line x1="${cx}" y1="${cy}" x2="495" y2="${cy}" stroke="#0284c7" stroke-width="2.8" />`;

    // 5. Semirrecta terminal (lado final del ángulo)
    const endX = cx + 232 * Math.cos(item.val);
    const endY = cy - 232 * Math.sin(item.val);
    html += `<line x1="${cx}" y1="${cy}" x2="${endX.toFixed(2)}" y2="${endY.toFixed(2)}" stroke="#0284c7" stroke-width="2.8" />`;

    // 6. Arco azul (con ligera espiral si supera 2*PI para visualizar las vueltas)
    const totalAngle = Math.abs(item.val);
    const numSamples = Math.max(45, Math.ceil(totalAngle * 35));
    let pathD = '';
    let lastX = cx + R;
    let lastY = cy;
    let prevX = lastX;
    let prevY = lastY;

    for (let i = 0; i <= numSamples; i++) {
      const t = i / numSamples;
      const theta = item.val * t;
      let rActual = R;
      if (totalAngle > 2 * Math.PI + 0.01) {
        rActual = R - 8 + (16 * t);
      }
      const px = cx + rActual * Math.cos(theta);
      const py = cy - rActual * Math.sin(theta);

      if (i === 0) {
        pathD += `M ${px.toFixed(2)} ${py.toFixed(2)}`;
      } else {
        pathD += ` L ${px.toFixed(2)} ${py.toFixed(2)}`;
      }
      if (i === numSamples - 1) {
        prevX = px;
        prevY = py;
      }
      if (i === numSamples) {
        lastX = px;
        lastY = py;
      }
    }

    html += `<path d="${pathD}" fill="none" stroke="#0284c7" stroke-width="2.7" />`;

    // Punta de flecha al final del arco
    const tangentAngle = Math.atan2(lastY - prevY, lastX - prevX);
    const arrowLen = 13;
    const a1 = tangentAngle + 2.65;
    const a2 = tangentAngle - 2.65;
    const ax1 = lastX + arrowLen * Math.cos(a1);
    const ay1 = lastY + arrowLen * Math.sin(a1);
    const ax2 = lastX + arrowLen * Math.cos(a2);
    const ay2 = lastY + arrowLen * Math.sin(a2);
    const amidX = lastX + (arrowLen * 0.55) * Math.cos(tangentAngle + Math.PI);
    const amidY = lastY + (arrowLen * 0.55) * Math.sin(tangentAngle + Math.PI);

    html += `<polygon points="${lastX.toFixed(2)},${lastY.toFixed(2)} ${ax1.toFixed(2)},${ay1.toFixed(2)} ${amidX.toFixed(2)},${amidY.toFixed(2)} ${ax2.toFixed(2)},${ay2.toFixed(2)}" fill="#0284c7" stroke="#0f172a" stroke-width="1.2" />`;

    // 7. Puntos y etiquetas exteriores
    if (item.div > 0) {
      const totalPuntos = Math.max(item.div, item.steps);
      const yaDibujados = new Set();

      for (let k = 1; k <= totalPuntos; k++) {
        const angK = item.dir * k * (Math.PI / item.div);
        const key = Math.round(((angK % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI) * 1000);

        const dotX = cx + R * Math.cos(angK);
        const dotY = cy - R * Math.sin(angK);

        if (!yaDibujados.has(key)) {
          yaDibujados.add(key);
          html += `<circle cx="${dotX.toFixed(2)}" cy="${dotY.toFixed(2)}" r="5.2" fill="#facc15" stroke="#1e293b" stroke-width="1.3" />`;

          // Etiqueta exterior sin pisar los ejes
          if (k <= item.steps) {
            const pos = obtenerPosEtiquetaExterior(cx, cy, R, angK);
            const signStr = item.dir < 0 ? "-" : "";

            if (item.div === 1) {
              const txt = k === 1 ? `${signStr}π` : `${signStr}${k}π`;
              html += `
                <rect x="${(pos.x - 14).toFixed(1)}" y="${(pos.y - 10).toFixed(1)}" width="28" height="20" rx="4" fill="rgba(255,255,255,0.88)" />
                <text x="${pos.x.toFixed(2)}" y="${(pos.y + 4).toFixed(2)}" font-size="13.5" font-weight="700" fill="#1e293b" text-anchor="middle">${txt}</text>
              `;
            } else {
              const numTxt = k === 1 ? `${signStr}π` : `${signStr}${k}π`;
              html += `
                <g transform="translate(${pos.x.toFixed(2)}, ${pos.y.toFixed(2)})">
                  <rect x="-15" y="-16" width="30" height="32" rx="4" fill="rgba(255,255,255,0.88)" />
                  <text x="0" y="-3" font-size="12" font-weight="700" fill="#1e293b" text-anchor="middle">${numTxt}</text>
                  <line x1="-11" y1="0" x2="11" y2="0" stroke="#1e293b" stroke-width="1.2" />
                  <text x="0" y="13" font-size="12" font-weight="700" fill="#1e293b" text-anchor="middle">${item.den}</text>
                </g>
              `;
            }
          }
        }
      }
    } else {
      // Caso especial: 6 radianes (6 puntos rojos numerados en el exterior)
      for (let rStep = 1; rStep <= 6; rStep++) {
        const dotX = cx + R * Math.cos(rStep);
        const dotY = cy - R * Math.sin(rStep);
        const pos = obtenerPosEtiquetaExterior(cx, cy, R - 8, rStep);

        html += `
          <circle cx="${dotX.toFixed(2)}" cy="${dotY.toFixed(2)}" r="4.8" fill="#ef4444" stroke="#7f1d1d" stroke-width="1.1" />
          <rect x="${(pos.x - 8).toFixed(1)}" y="${(pos.y - 9).toFixed(1)}" width="16" height="18" rx="3" fill="rgba(255,255,255,0.88)" />
          <text x="${pos.x.toFixed(2)}" y="${(pos.y + 4.5).toFixed(2)}" font-size="13.5" font-weight="800" fill="#dc2626" text-anchor="middle">${rStep}</text>
        `;
      }
    }

    // 8. Punto negro de origen (1, 0)
    html += `<circle cx="${cx + R}" cy="${cy}" r="5" fill="#0f172a" />`;

    svg.innerHTML = html;
  }

  function actualizarBotones() {
    const botones = document.querySelectorAll('#rad-grid-botones .rad-btn-item');
    botones.forEach(btn => {
      const id = parseInt(btn.dataset.id, 10);
      if (id === activeId) {
        btn.style.backgroundColor = '#1d4ed8';
        btn.style.color = '#ffffff';
        btn.style.borderColor = '#1e3a8a';
        btn.style.boxShadow = 'inset 0 2px 4px rgba(0,0,0,0.25)';
      } else {
        btn.style.backgroundColor = '#ffffff';
        btn.style.color = '#1e293b';
        btn.style.borderColor = '#93c5fd';
        btn.style.boxShadow = '0 1px 2px rgba(0,0,0,0.06)';
      }
    });
  }

  function seleccionarAngulo(id) {
    activeId = id;
    const item = angulosData.find(a => a.id === id);
    if (!item) return;

    document.getElementById('rad-estado-inicial').style.display = 'none';
    document.getElementById('rad-estado-activo').style.display = 'block';
    document.getElementById('rad-titulo-angulo').innerHTML = renderTituloHTML(item);
    document.getElementById('rad-explicacion').innerHTML = item.desc;

    actualizarBotones();
    dibujarEscena(item);
  }

  function inicializar() {
    const grid = document.getElementById('rad-grid-botones');
    if (!grid) return;

    grid.innerHTML = '';
    angulosData.forEach(item => {
      const btn = document.createElement('div');
      btn.className = 'rad-btn-item';
      btn.dataset.id = item.id;
      btn.setAttribute('role', 'button');
      btn.setAttribute('tabindex', '0');
      btn.textContent = item.label;

      btn.style.cssText = `
        background-color: #ffffff;
        color: #1e293b;
        border: 1.5px solid #93c5fd;
        border-radius: 6px;
        padding: 12px 4px;
        text-align: center;
        font-size: 1.05rem;
        font-weight: 700;
        cursor: pointer;
        user-select: none;
        transition: all 0.15s ease;
        box-shadow: 0 1px 2px rgba(0,0,0,0.06);
      `;

      btn.addEventListener('mouseenter', function() {
        if (activeId !== item.id) {
          this.style.backgroundColor = '#dbeafe';
          this.style.borderColor = '#2563eb';
        }
      });
      btn.addEventListener('mouseleave', function() {
        if (activeId !== item.id) {
          this.style.backgroundColor = '#ffffff';
          this.style.borderColor = '#93c5fd';
        }
      });

      btn.addEventListener('click', function() {
        seleccionarAngulo(item.id);
      });

      grid.appendChild(btn);
    });

    dibujarEscena(null);
  }

  setTimeout(inicializar, 100);
})();
