<script>
(function() {
  const cx = 170;
  const cy = 170;
  const R_circ = 100;
  const R_rayo = 132;

  let anguloObjetivoDeg = 195;
  let animacionId = null;

  const BANCO_ANGULOS = [
    45, 70, 120, 150, 195, 225, 260, 310, 410,
    -40, -75, -115, -145, -195, -230, -280, -320, -405
  ];
  let ultimoAngulo = null;

  function elegirNuevoAngulo() {
    let candidato;
    do {
      candidato = BANCO_ANGULOS[Math.floor(Math.random() * BANCO_ANGULOS.length)];
    } while (candidato === ultimoAngulo);
    ultimoAngulo = candidato;
    return candidato;
  }

  function crearPathArco(degActual) {
    const pasos = Math.max(12, Math.ceil(Math.abs(degActual) / 4));
    let d = "";
    for (let i = 0; i <= pasos; i++) {
      const t = i / pasos;
      const aDeg = degActual * t;
      const aRad = (aDeg * Math.PI) / 180;
      const rActual = 52 + (Math.abs(aDeg) / 360) * 14;
      const x = cx + rActual * Math.cos(aRad);
      const y = cy - rActual * Math.sin(aRad);
      d += (i === 0 ? `M ${x.toFixed(2)} ${y.toFixed(2)}` : ` L ${x.toFixed(2)} ${y.toFixed(2)}`);
    }
    return d;
  }

  function crearPathSector(degActual) {
    const degLimitado = Math.max(-359.9, Math.min(359.9, degActual));
    if (Math.abs(degLimitado) < 1) return "";
    const rad = (degLimitado * Math.PI) / 180;
    const xEnd = cx + R_circ * Math.cos(rad);
    const yEnd = cy - R_circ * Math.sin(rad);
    const largeArc = Math.abs(degLimitado) > 180 ? 1 : 0;
    const sweep = degLimitado > 0 ? 0 : 1;
    return `M ${cx} ${cy} L ${cx + R_circ} ${cy} A ${R_circ} ${R_circ} 0 ${largeArc} ${sweep} ${xEnd.toFixed(2)} ${yEnd.toFixed(2)} Z`;
  }

  function renderFrame(progreso) {
    const capa = document.getElementById('sa-capa-animacion');
    if (!capa) return;

    let html = "";

    // Fase 1 (0% a 22%): Semirrecta fija desde el origen
    const pBase = Math.min(1, progreso / 0.22);
    const xBase = cx + R_rayo * pBase;

    html += `<line x1="${cx}" y1="${cy}" x2="${xBase.toFixed(2)}" y2="${cy}" stroke="#475569" stroke-width="2.5" stroke-linecap="round" />`;
    html += `<circle cx="${cx}" cy="${cy}" r="3.5" fill="#ea580c" />`;

    if (pBase >= 1) {
      html += `<circle cx="${cx + R_circ}" cy="${cy}" r="4.5" fill="#ea580c" stroke="#ffffff" stroke-width="1.5" />`;
    }

    // Fase 2 (22% a 100%): Barrido del ángulo
    if (progreso > 0.22) {
      const pGiro = (progreso - 0.22) / 0.78;
      const ease = 1 - Math.pow(1 - pGiro, 3);
      const degActual = anguloObjetivoDeg * ease;
      const radActual = (degActual * Math.PI) / 180;

      const pathSector = crearPathSector(degActual);
      if (pathSector) {
        html += `<path d="${pathSector}" fill="rgba(234, 88, 12, 0.14)" />`;
      }

      const xTerm = cx + R_rayo * Math.cos(radActual);
      const yTerm = cy - R_rayo * Math.sin(radActual);
      html += `<line x1="${cx}" y1="${cy}" x2="${xTerm.toFixed(2)}" y2="${yTerm.toFixed(2)}" stroke="#ea580c" stroke-width="2.8" stroke-linecap="round" />`;

      if (Math.abs(degActual) > 4) {
        const pathArco = crearPathArco(degActual);
        html += `<path d="${pathArco}" fill="none" stroke="#c2410c" stroke-width="2.4" stroke-linecap="round" />`;

        const rFlecha = 52 + (Math.abs(degActual) / 360) * 14;
        const fx = cx + rFlecha * Math.cos(radActual);
        const fy = cy - rFlecha * Math.sin(radActual);

        const dir = degActual >= 0 ? 1 : -1;
        const tx = -dir * Math.sin(radActual);
        const ty = -dir * Math.cos(radActual);
        const anguloFlecha = Math.atan2(ty, tx) * (180 / Math.PI);

        html += `
          <g transform="translate(${fx.toFixed(2)}, ${fy.toFixed(2)}) rotate(${anguloFlecha.toFixed(2)})">
            <polygon points="3,0 -7,-4.5 -5,0 -7,4.5" fill="#c2410c" />
          </g>
        `;
      }
    }

    capa.innerHTML = html;
  }

  function iniciarAnimacion() {
    if (animacionId) cancelAnimationFrame(animacionId);
    const duracionMs = 2300; // Animación ligeramente más pausada
    let inicio = null;

    function paso(timestamp) {
      if (!inicio) inicio = timestamp;
      const transcurrido = timestamp - inicio;
      const progreso = Math.min(1, transcurrido / duracionMs);

      renderFrame(progreso);

      if (progreso < 1) {
        animacionId = requestAnimationFrame(paso);
      } else {
        animacionId = null;
      }
    }

    animacionId = requestAnimationFrame(paso);
  }

  function resetearBotonesOpcion() {
    const btnPos = document.getElementById('sa-opt-pos');
    const btnNeg = document.getElementById('sa-opt-neg');
    [btnPos, btnNeg].forEach(btn => {
      if (!btn) return;
      btn.style.backgroundColor = '#ffffff';
      btn.style.color = '#9a3412';
      btn.style.borderColor = '#fdba74';
    });
  }

  function evaluarRespuesta(eleccion) {
    const fb = document.getElementById('sa-feedback-box');
    const btnPos = document.getElementById('sa-opt-pos');
    const btnNeg = document.getElementById('sa-opt-neg');

    resetearBotonesOpcion();

    const btnSeleccionado = eleccion === 'positivo' ? btnPos : btnNeg;
    const signoCorrecto = anguloObjetivoDeg > 0 ? 'positivo' : 'negativo';
    const esCorrecto = (eleccion === signoCorrecto);

    if (esCorrecto) {
      btnSeleccionado.style.backgroundColor = '#16a34a';
      btnSeleccionado.style.color = '#ffffff';
      btnSeleccionado.style.borderColor = '#15803d';

      fb.style.backgroundColor = '#f0fdf4';
      fb.style.borderColor = '#16a34a';
      fb.style.borderStyle = 'solid';
      fb.style.color = '#15803d';

      if (signoCorrecto === 'positivo') {
        fb.innerHTML = `<div><strong>¡Correcto! El ángulo es POSITIVO (+).</strong><br><span style="font-size:0.92rem; font-weight:500;">Gira en sentido contrario a las agujas del reloj (antihorario) desde el semieje positivo \(OX\).</span></div>`;
      } else {
        fb.innerHTML = `<div><strong>¡Correcto! El ángulo es NEGATIVO (−).</strong><br><span style="font-size:0.92rem; font-weight:500;">Gira en el mismo sentido que las agujas del reloj (horario) desde el semieje positivo \(OX\).</span></div>`;
      }
    } else {
      btnSeleccionado.style.backgroundColor = '#dc2626';
      btnSeleccionado.style.color = '#ffffff';
      btnSeleccionado.style.borderColor = '#b91c1c';

      fb.style.backgroundColor = '#fef2f2';
      fb.style.borderColor = '#dc2626';
      fb.style.borderStyle = 'solid';
      fb.style.color = '#b91c1c';

      const pista = signoCorrecto === 'positivo'
        ? 'Fíjate en la flecha: sube girando en sentido <strong>contrario</strong> a las agujas del reloj.'
        : 'Fíjate en la flecha: baja girando en el <strong>mismo sentido</strong> que las agujas del reloj.';

      fb.innerHTML = `<div><strong>Incorrecto. Inténtalo de nuevo.</strong><br><span style="font-size:0.92rem; font-weight:500;">${pista}</span></div>`;
    }

    if (window.MathJax && window.MathJax.typesetPromise) {
      window.MathJax.typesetPromise([fb]).catch(function(){});
    }
  }

  function nuevoEjercicio() {
    anguloObjetivoDeg = elegirNuevoAngulo();
    resetearBotonesOpcion();

    const fb = document.getElementById('sa-feedback-box');
    if (fb) {
      fb.style.backgroundColor = '#ffffff';
      fb.style.borderColor = '#fdba74';
      fb.style.borderStyle = 'dashed';
      fb.style.color = '#9a3412';
      fb.innerHTML = 'Pulsa sobre una de las dos opciones para comprobar tu respuesta.';
    }

    iniciarAnimacion();
  }

  function init() {
    const btnPos = document.getElementById('sa-opt-pos');
    const btnNeg = document.getElementById('sa-opt-neg');
    const btnRepetir = document.getElementById('sa-btn-repetir');
    const btnNuevo = document.getElementById('sa-btn-nuevo');

    if (btnPos) btnPos.addEventListener('click', () => evaluarRespuesta('positivo'));
    if (btnNeg) btnNeg.addEventListener('click', () => evaluarRespuesta('negativo'));
    if (btnRepetir) btnRepetir.addEventListener('click', iniciarAnimacion);
    if (btnNuevo) btnNuevo.addEventListener('click', nuevoEjercicio);

    // Efectos hover mediante JS para que eXeLearning no los borre
    if (btnRepetir) {
      btnRepetir.addEventListener('mouseenter', () => { btnRepetir.style.backgroundColor = '#fff7ed'; btnRepetir.style.borderColor = '#ea580c'; });
      btnRepetir.addEventListener('mouseleave', () => { btnRepetir.style.backgroundColor = '#ffffff'; btnRepetir.style.borderColor = '#fdba74'; });
    }
    if (btnNuevo) {
      btnNuevo.addEventListener('mouseenter', () => { btnNuevo.style.backgroundColor = '#c2410c'; btnNuevo.style.borderColor = '#c2410c'; });
      btnNuevo.addEventListener('mouseleave', () => { btnNuevo.style.backgroundColor = '#ea580c'; btnNuevo.style.borderColor = '#ea580c'; });
    }

    nuevoEjercicio();
  }

  setTimeout(init, 100);
})();
</script>
